    "\n"
    "<script>\n"
    "/* =========================================================\n"
    "   AiPiClaw Config Portal \x2014 \x4e09\x6b65\x5411\x5bfc JS\n"
    "   =========================================================\n"
    "   \x4f9d\x8d56: \x65e0\n"
    "   \x63a5\x53e3: 7\x4e2a REST API \x7aef\x70b9 (\x8be6\x89c1\x6587\x4ef6\x5934)\n"
    "   \x6d41\x7a0b: Step1 WiFi \x2192 Step2 LLM \x2192 Step3 Apply \x2192 Chat\n"
    "   ========================================================= */\n"
    "\n"
    "// ---- \x5168\x5c40\x72b6\x6001 ----\n"
    "let state = {\n"
    "  step: 1,\n"
    "  selectedSSID: '',\n"
    "  ssid: '',\n"
    "  pwd: '',\n"
    "  provider: 'minimax',\n"
    "  model: 'MiniMax-M2.5',\n"
    "  key: '',\n"
    "  scanning: false,\n"
    "  connecting: false\n"
    "};\n"
    "\n"
    "// ---- \x6b65\x9aa4\x5207\x6362 ----\n"
    "function goToStep(n) {\n"
    "  document.querySelectorAll('.step').forEach(el => el.classList.remove('active'));\n"
    "  document.getElementById('step' + n).classList.add('active');\n"
    "  state.step = n;\n"
    "  document.getElementById('step-indicator').textContent = n + ' / 3';\n"
    "}\n"
    "\n"
    "// ---- \x5de5\x5177: \x663e\x793a\x6d88\x606f ----\n"
    "function showMsg(id, type, text) {\n"
    "  const el = document.getElementById(id);\n"
    "  el.className = 'msg show ' + type;\n"
    "  el.textContent = text;\n"
    "}\n"
    "function hideMsg(id) {\n"
    "  document.getElementById(id).className = 'msg';\n"
    "  document.getElementById(id).textContent = '';\n"
    "}\n"
    "\n"
    "// ---- Step 1: WiFi \x626b\x63cf ----\n"
    "function scanWifi() {\n"
    "  if (state.scanning) return;\n"
    "  state.scanning = true;\n"
    "  const btn = document.getElementById('scan-btn');\n"
    "  btn.disabled = true;\n"
    "  btn.textContent = '\x23f3 \x626b\x63cf\x4e2d...';\n"
    "  document.getElementById('scan-status').textContent = '';\n"
    "  document.getElementById('ap-list').innerHTML = '';\n"
    "\n"
    "  // POST \x89e6\x53d1\x626b\x63cf\n"
    "  fetch('/api/wifi/scan', { method: 'POST' })\n"
    "    .then(r => r.json())\n"
    "    .then(d => {\n"
    "      // \x8f6e\x8be2\x626b\x63cf\x7ed3\x679c\n"
    "      return new Promise((resolve, reject) => {\n"
    "        const poll = () => {\n"
    "          fetch('/api/wifi/scan')\n"
    "            .then(r => r.json())\n"
    "            .then(res => {\n"
    "              if (res.ssids && res.ssids.length > 0) {\n"
    "                resolve(res);\n"
    "              } else {\n"
    "                setTimeout(poll, 500);\n"
    "              }\n"
    "            })\n"
    "            .catch(reject);\n"
    "        };\n"
    "        setTimeout(poll, 500);\n"
    "      });\n"
    "    })\n"
    "    .then(res => renderAPList(res.ssids))\n"
    "    .catch(err => {\n"
    "      showMsg('wifi-msg', 'error', '\x626b\x63cf\x5931\x8d25: ' + err.message);\n"
    "    })\n"
    "    .finally(() => {\n"
    "      state.scanning = false;\n"
    "      btn.disabled = false;\n"
    "      btn.textContent = '\x1f4e1 \x91cd\x65b0\x626b\x63cf';\n"
    "    });\n"
    "}\n"
    "\n"
    "function renderAPList(ssids) {\n"
    "  const list = document.getElementById('ap-list');\n"
    "  list.innerHTML = '';\n"
    "  if (!ssids || ssids.length === 0) {\n"
    "    document.getElementById('scan-status').textContent = '\x672a\x53d1\x73b0 WiFi \x7f51\x7edc';\n"
    "    return;\n"
    "  }\n"
    "  document.getElementById('scan-status').textContent = '\x627e\x5230 ' + ssids.length + ' \x4e2a\x7f51\x7edc';\n"
    "  ssids.forEach(ap => {\n"
    "    const card = document.createElement('div');\n"
    "    card.className = 'ap-card';\n"
    "    // WiFi \x4fe1\x53f7\x56fe\x6807: \x6839\x636e\x4fe1\x53f7\x5f3a\x5ea6\x9009\x4e0d\x540c\x683c\x6570\n"
    "    const bars = ap.rssi > -50 ? 3 : ap.rssi > -70 ? 2 : 1;\n"
    "    card.innerHTML =\n"
    "      '<div class=\"icon\">' + '\x1f4f6' + '</div>' +\n"
    "      '<div class=\"info\"><div class=\"ssid\">' + escHtml(ap.ssid) + '</div>' +\n"
    "      '<div class=\"meta\">' + (ap.auth || 'WPA2') + '</div></div>' +\n"
    "      '<div class=\"rssi\">' + ap.rssi + ' dBm</div>';\n"
    "    card.onclick = function() {\n"
    "      document.querySelectorAll('.ap-card').forEach(c => c.classList.remove('selected'));\n"
    "      card.classList.add('selected');\n"
    "      state.selectedSSID = ap.ssid;\n"
    "      state.ssid = ap.ssid;\n"
    "      document.getElementById('connect-btn').disabled = false;\n"
    "      document.getElementById('wifi-pwd').focus();\n"
    "    };\n"
    "    list.appendChild(card);\n"
    "  });\n"
    "}\n"
    "\n"
    "// ---- Step 1: WiFi \x8fde\x63a5 ----\n"
    "function connectWifi() {\n"
    "  if (!state.ssid) { showMsg('wifi-msg', 'error', '\x8bf7\x5148\x9009\x62e9\x4e00\x4e2a WiFi \x7f51\x7edc'); return; }\n"
    "  if (state.connecting) return;\n"
    "  state.connecting = true;\n"
    "  state.pwd = document.getElementById('wifi-pwd').value;\n"
    "  const btn = document.getElementById('connect-btn');\n"
    "  btn.disabled = true;\n"
    "  btn.textContent = '\x23f3 \x8fde\x63a5\x4e2d...';\n"
    "  hideMsg('wifi-msg');\n"
    "\n"
    "  fetch('/api/wifi/connect', {\n"
    "    method: 'POST',\n"
    "    headers: { 'Content-Type': 'application/json' },\n"
    "    body: JSON.stringify({ ssid: state.ssid, password: state.pwd })\n"
    "  })\n"
    "  .then(r => r.json())\n"
    "  .then(d => {\n"
    "    showMsg('wifi-msg', 'success', 'WiFi \x51ed\x636e\x5df2\x4fdd\x5b58\xff0c\x6b63\x5728\x8fde\x63a5...');\n"
    "    // \x8f6e\x8be2\x8fde\x63a5\x72b6\x6001\n"
    "    return pollWifiStatus();\n"
    "  })\n"
    "  .then(status => {\n"
    "    if (status.status === 'connected') {\n"
    "      showMsg('wifi-msg', 'success', '\x2705 WiFi \x5df2\x8fde\x63a5 \x2014 ' + (status.ip || ''));\n"
    "      setTimeout(() => goToStep(2), 800);\n"
    "    } else {\n"
    "      showMsg('wifi-msg', 'info', 'WiFi \x51ed\x636e\x5df2\x4fdd\x5b58\xff0c\x8fde\x63a5\x53ef\x80fd\x9700\x8981 10-15 \x79d2');\n"
    "      setTimeout(() => goToStep(2), 1500);\n"
    "    }\n"
    "  })\n"
    "  .catch(err => {\n"
    "    showMsg('wifi-msg', 'error', '\x8fde\x63a5\x5931\x8d25: ' + err.message);\n"
    "    btn.disabled = false;\n"
    "    btn.textContent = '\x8fde\x63a5 WiFi';\n"
    "    state.connecting = false;\n"
    "  });\n"
    "}\n"
    "\n"
    "function pollWifiStatus(maxRetries) {\n"
    "  maxRetries = maxRetries || 15;\n"
    "  return new Promise((resolve, reject) => {\n"
    "    let tries = 0;\n"
    "    const poll = () => {\n"
    "      tries++;\n"
    "      fetch('/api/wifi/status')\n"
    "        .then(r => r.json())\n"
    "        .then(s => {\n"
    "          if (s.status === 'connected') resolve(s);\n"
    "          else if (tries >= maxRetries) resolve(s);  // \x8d85\x65f6\x4e5f\x8fd4\x56de\n"
    "          else setTimeout(poll, 800);\n"
    "        })\n"
    "        .catch(() => {\n"
    "          if (tries >= maxRetries) reject(new Error('\x72b6\x6001\x67e5\x8be2\x8d85\x65f6'));\n"
    "          else setTimeout(poll, 800);\n"
    "        });\n"
    "    };\n"
    "    setTimeout(poll, 500);\n"
    "  });\n"
    "}\n"
    "\n"
    "// ---- Step 2: LLM \x914d\x7f6e ----\n"
    "function saveLLM() {\n"
    "  state.provider = document.getElementById('llm-provider').value;\n"
    "  state.model = document.getElementById('llm-model').value || state.model;\n"
    "  state.key = document.getElementById('llm-key').value;\n"
    "  const btn = document.getElementById('llm-save-btn');\n"
    "  btn.disabled = true;\n"
    "  btn.textContent = '\x23f3 \x4fdd\x5b58\x4e2d...';\n"
    "  hideMsg('llm-msg');\n"
    "\n"
    "  fetch('/api/llm/config', {\n"
    "    method: 'POST',\n"
    "    headers: { 'Content-Type': 'application/json' },\n"
    "    body: JSON.stringify({ provider: state.provider, model: state.model, api_key: state.key })\n"
    "  })\n"
    "  .then(r => r.json())\n"
    "  .then(d => {\n"
    "    showMsg('llm-msg', 'success', '\x2705 AI \x914d\x7f6e\x5df2\x4fdd\x5b58');\n"
    "    setTimeout(() => goToStep(3), 800);\n"
    "  })\n"
    "  .catch(err => {\n"
    "    showMsg('llm-msg', 'error', '\x4fdd\x5b58\x5931\x8d25: ' + err.message);\n"
    "    btn.disabled = false;\n"
    "    btn.textContent = '\x1f4be \x4fdd\x5b58\x914d\x7f6e';\n"
    "  });\n"
    "}\n"
    "\n"
    "// ---- Step 3: \x5e94\x7528 & \x542f\x52a8 ----\n"
    "function applyAndStart() {\n"
    "  // \x586b\x5145\x6458\x8981\n"
    "  document.getElementById('summary-ssid').textContent = state.ssid || '\x2014';\n"
    "  document.getElementById('summary-provider').textContent = state.provider || '\x2014';\n"
    "  document.getElementById('summary-model').textContent = state.model || '\x2014';\n"
    "  document.getElementById('summary-key').textContent = state.key ? '\x2022\x2022\x2022\x2022' + state.key.slice(-4) : '\x2014';\n"
    "\n"
    "  const btn = document.getElementById('apply-btn');\n"
    "  btn.disabled = true;\n"
    "  btn.textContent = '\x23f3 \x6b63\x5728\x5e94\x7528...';\n"
    "  hideMsg('apply-msg');\n"
    "\n"
    "  fetch('/api/apply', { method: 'POST' })\n"
    "    .then(r => r.json())\n"
    "    .then(d => {\n"
    "      showMsg('apply-msg', 'success', '\x2705 \x914d\x7f6e\x5df2\x5e94\x7528\xff01\x6b63\x5728\x5207\x6362\x5230\x804a\x5929\x6a21\x5f0f...');\n"
    "      // \x663e\x793a\x8fc7\x6e21\x52a8\x753b\n"
    "      document.getElementById('transition').classList.add('show');\n"
    "      // \x7b49\x5f85\x8bbe\x5907\x91cd\x542f + WS \x670d\x52a1\x5668\x542f\x52a8\n"
    "      setTimeout(switchToChat, 8000);\n"
    "    })\n"
    "    .catch(err => {\n"
    "      showMsg('apply-msg', 'error', '\x5e94\x7528\x5931\x8d25: ' + err.message);\n"
    "      btn.disabled = false;\n"
    "      btn.textContent = '\x1f680 \x4fdd\x5b58\x5e76\x542f\x52a8';\n"
    "    });\n"
    "}\n"
    "\n"
    "// ---- \x5207\x6362\x5230\x804a\x5929\x754c\x9762 ----\n"
    "function switchToChat() {\n"
    "  const host = '192.168.4.1';\n"
    "  const wsUrl = 'ws://' + host + ':18789';\n"
    "  document.querySelector('#transition .text').textContent = '\x8fde\x63a5\x804a\x5929\x670d\x52a1...';\n"
    "\n"
    "  // \x5c1d\x8bd5\x8fde\x63a5 WebSocket\n"
    "  let retries = 0;\n"
    "  const maxRetries = 20;\n"
    "  function tryConnect() {\n"
    "    const ws = new WebSocket(wsUrl);\n"
    "    const t = setTimeout(function() {\n"
    "      ws.onclose = null;\n"
    "      ws.close();\n"
    "      retries++;\n"
    "      if (retries < maxRetries) {\n"
    "        document.querySelector('#transition .text').textContent =\n"
    "          '\x8fde\x63a5\x4e2d (' + retries + '/' + maxRetries + ')...';\n"
    "        setTimeout(tryConnect, 1500);\n"
    "      } else {\n"
    "        document.querySelector('#transition .text').textContent =\n"
    "          '\x8fde\x63a5\x8d85\x65f6\xff0c\x8bf7\x5237\x65b0\x9875\x9762\x91cd\x8bd5';\n"
    "      }\n"
    "    }, 3000);\n"
    "    ws.onopen = function() {\n"
    "      clearTimeout(t);\n"
    "      // \x5207\x6362\x5230\x804a\x5929\x754c\x9762: \x91cd\x5b9a\x5411\x5230\x6839\x8def\x5f84\n"
    "      window.location.href = 'http://' + host + '/';\n"
    "    };\n"
    "    ws.onclose = function() {\n"
    "      clearTimeout(t);\n"
    "    };\n"
    "  }\n"
    "  tryConnect();\n"
    "}\n"
    "\n"
    "// ---- \x5de5\x5177: HTML \x8f6c\x4e49 ----\n"
    "function escHtml(s) {\n"
    "  if (!s) return '';\n"
    "  const m = {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'};\n"
    "  return String(s).replace(/[&<>\"']/g, c => m[c]);\n"
    "}\n"
    "\n"
    "// ---- \x81ea\x52a8\x52a0\x8f7d\x5df2\x6709\x914d\x7f6e ----\n"
    "function loadExistingConfig() {\n"
    "  fetch('/api/llm/config')\n"
    "    .then(r => r.json())\n"
    "    .then(d => {\n"
    "      if (d.provider) {\n"
    "        document.getElementById('llm-provider').value = d.provider;\n"
    "        state.provider = d.provider;\n"
    "      }\n"
    "      if (d.model) {\n"
    "        document.getElementById('llm-model').value = d.model;\n"
    "        state.model = d.model;\n"
    "      }\n"
    "      if (d.api_key && d.api_key.length > 0) {\n"
    "        document.getElementById('llm-key').placeholder = '\x5df2\x914d\x7f6e\xff0c\x53ef\x7559\x7a7a\x4fdd\x6301\x4e0d\x53d8';\n"
    "      }\n"
    "    })\n"
    "    .catch(() => {});\n"
    "  // \x4e5f\x68c0\x67e5 WiFi \x72b6\x6001\n"
    "  fetch('/api/wifi/status')\n"
    "    .then(r => r.json())\n"
    "    .then(s => {\n"
    "      if (s.ssid) {\n"
    "        state.ssid = s.ssid;\n"
    "        state.selectedSSID = s.ssid;\n"
    "      }\n"
    "    })\n"
    "    .catch(() => {});\n"
    "}\n"
    "\n"
    "// ---- \x521d\x59cb\x5316 ----\n"
    "loadExistingConfig();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "";

#endif /* _CONFIG_UI_H_ */
